// Small helpers shared by the core logic. Inlined into each Code node by scripts/build-workflows.js.

const clean = (v) => String(v ?? '').trim();
const lower = (v) => clean(v).toLowerCase();
const truthy = (v) => ['true', 'yes', '1', 'y'].includes(lower(v));
// Slack markdown: escape its three control characters so names, titles, lookup text or AI output
// can't add links, @channel pings or mentions to an alert.
const mdEsc = (v) => clean(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Only plain http(s) links, with nothing that could break out of a Slack or HTML link (no javascript: or data:).
const safeUrl = (v) => { const u = clean(v); return /^https?:\/\/[^\s<>|"'`]+$/i.test(u) ? u : ''; };

function parseJson(value, fallback) {
  if (value && typeof value === 'object') return value;
  const s = clean(value);
  if (!s) return fallback;
  try { return JSON.parse(s); } catch (e) { return fallback; }
}

function normDomain(s) {
  let d = lower(s);
  if (!d) return '';
  d = d.replace(/^[a-z]+:\/\//, '').replace(/^www\./, '').split('/')[0].split('?')[0];
  if (d.includes('@')) d = d.split('@').pop();
  return d;
}

function splitName(full) {
  const parts = clean(full).split(/\s+/).filter(Boolean);
  if (!parts.length) return { first_name: '', last_name: '' };
  if (parts.length === 1) return { first_name: parts[0], last_name: '' };
  return { first_name: parts[0], last_name: parts.slice(1).join(' ') };
}

// Stable 1, 2 or 3 from a contact_id, so a third of the list is swept each month without anyone assigning groups.
function sweepGroupFor(id) {
  let h = 0;
  const s = clean(id);
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
  return String((h % 3) + 1);
}

const isoDay = (d) => d.toISOString().slice(0, 10);

// Team directory (Config): { "<email, CRM owner id or name>": { name, email, slack_id, crm_id, salesloft_user_id }, "default": {...} }
function loadDirectory(cfg) {
  const raw = parseJson(cfg.team_directory, {}) || {};
  const dir = {};
  for (const [k, v] of Object.entries(raw)) dir[lower(k)] = v && typeof v === 'object' ? v : {};
  return dir;
}

// Fills an owner's missing name / email / Slack ID / CRM ID / sequence user ID from the directory.
function resolveOwner(dir, owner, useDefault = true) {
  const o = owner || {};
  let entry = dir[lower(o.email)] || dir[lower(o.crm_id)] || dir[lower(o.name)];
  const hasOwner = clean(o.name) || clean(o.email) || clean(o.crm_id);
  if (!entry && !hasOwner && useDefault) entry = dir.default;
  entry = entry || {};
  return {
    name: clean(o.name) || clean(entry.name),
    email: lower(o.email) || lower(entry.email),
    slack_id: clean(o.slack_id) || clean(entry.slack_id),
    crm_id: clean(o.crm_id) || clean(entry.crm_id),
    sequence_user_id: clean(o.sequence_user_id) || clean(entry.salesloft_user_id || entry.sequence_user_id),
  };
}

// Lookup callback: turns a result sent back later by an async lookup tool (Clay) into a cache row.
// The next Daily Run picks up every READY row and finishes those investigations without spending another credit.
// Pure function: tested in test/, inlined into the Lookup Callback workflow.


function normalizeCallback(body, existingRows, nowInput) {
  const now = nowInput ? new Date(nowInput) : new Date();
  const b = body && typeof body === 'object' ? (body.body && typeof body.body === 'object' ? body.body : body) : {};
  const pick = (...keys) => {
    for (const k of keys) {
      const v = k.split('.').reduce((o, part) => (o && typeof o === 'object' ? o[part] : undefined), b);
      if (v !== undefined && v !== null && typeof v !== 'object' && clean(v) !== '') return clean(v);
    }
    return '';
  };
  const contactId = pick('valari_contact_id', 'contact_id', 'contactId');
  if (!contactId) return null;
  const provider = lower(pick('provider', 'source')) || 'clay';
  const company = pick('company_name', 'job_company_name', 'company', 'organization_name', 'current_company');
  const title = pick('job_title', 'title', 'current_title');
  const summary = {
    found: !!(company || title),
    provider,
    full_name: pick('full_name', 'name'),
    linkedin_url: pick('linkedin_url', 'linkedin'),
    location: pick('location'),
    job_title: title,
    job_company_name: company,
    job_company_website: normDomain(pick('company_domain', 'job_company_website', 'domain', 'company_website', 'website')),
    job_start_date: pick('job_start_date', 'start_date', 'started_at'),
    job_last_changed: '',
    job_last_verified: pick('job_last_verified', 'verified_at'),
    experience: [],
    email: lower(pick('work_email', 'email', 'new_email')),
    email_status: lower(pick('email_status')),
  };
  if (!summary.found) summary.note = `${provider} found no current job for this person. This is not evidence that they moved.`;
  const existing = (existingRows || []).find((r) => clean(r.contact_id) === contactId) || {};
  // Only accept an answer Valari is waiting for, and only once: a replayed or unexpected callback is ignored,
  // so it can't overwrite a result, trigger duplicate alerts or point an enrollment at another address.
  if (lower(existing.pending) !== 'true') return null;
  const tried = parseJson(existing.tried_json, {}) || {};
  tried[provider] = now.toISOString();
  return {
    contact_id: contactId,
    provider,
    found: summary.found ? 'TRUE' : 'FALSE',
    // READY: the answer is in; the next Daily Run investigates everyone READY in one batch.
    pending: 'READY',
    summary_json: JSON.stringify(summary),
    looked_up_at: now.toISOString(),
    tried_json: JSON.stringify(tried),
    signal_json: clean(existing.signal_json),
  };
}

// ---- n8n entry ----
const existing = $input.all().map((i) => i.json).filter((r) => r && r.contact_id);
const row = normalizeCallback($('Webhook').first().json, existing);
if (!row) { console.log('Callback ignored: no valari_contact_id, or Valari was not waiting for this result'); return []; }
return [{ json: row }];
